1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Derives an owner's {@code identityKey} &mdash; the single value all duplicate detection is now
10	 * expressed through.
11	 *
12	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
13	 * Two owners are duplicates only when their <em>whole</em> keys are equal: because the telephone is
14	 * part of the key, two members of the same household (same {@code householdId}) with different
15	 * telephones have different keys and are both allowed.
16	 */
17	public final class OwnerIdentity {
18	
19	    private OwnerIdentity() {
20	    }
21	
22	    /**
23	     * Builds the identity key from an owner's parts. The telephone is expected to already be in
24	     * E.164 form (as stored); the email is compared lower-cased and a null/blank email or
25	     * {@code householdId} contributes an empty segment.
26	     */
27	    public static String key(String telephone, String email, String householdId) {
28	        String tel = telephone == null ? "" : telephone;
29	        String em = (email == null || email.isBlank()) ? "" : email.trim().toLowerCase(Locale.ROOT);
30	        String hh = householdId == null ? "" : householdId;
31	        return tel + "|" + em + "|" + hh;
32	    }
33	
34	    /**
35	     * The hash segment of an owner's {@code '<REGION>-<HASH8>'} customer code: the first 8
36	     * upper-case hex characters of SHA-256 over the normalised telephone concatenated with the
37	     * last name. The telephone is expected to already be in E.164 form (as stored).
38	     */
39	    public static String customerHash(String normalizedTelephone, String lastName) {
40	        String tel = normalizedTelephone == null ? "" : normalizedTelephone;
41	        String last = lastName == null ? "" : lastName;
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256")
44	                .digest((tel + last).getBytes(StandardCharsets.UTF_8));
45	            StringBuilder sb = new StringBuilder(8);
46	            for (int i = 0; i < 4; i++) {
47	                sb.append(String.format("%02X", digest[i]));
48	            }
49	            return sb.toString();
50	        }
51	        catch (NoSuchAlgorithmException ex) {
52	            throw new IllegalStateException(ex);
53	        }
54	    }
55	
56	    /**
57	     * The household's stable, deterministic identifier: the first 12 upper-case hex characters of
58	     * SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners sharing a last name and
59	     * postcode therefore resolve to the same value automatically, regardless of creation order or
60	     * whether they opted into {@code sharesHousehold}. Returns {@code null} when no postcode is
61	     * given, since a household is keyed on (last name, postcode) and cannot form without one.
62	     */
63	    public static String householdId(String lastName, String postcode) {
64	        if (postcode == null || postcode.isBlank()) {
65	            return null;
66	        }
67	        try {
68	            String key = normalizeName(lastName) + "|" + postcode;
69	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
70	            StringBuilder sb = new StringBuilder(12);
71	            for (int i = 0; i < 6; i++) {
72	                sb.append(String.format("%02X", digest[i]));
73	            }
74	            return sb.toString();
75	        }
76	        catch (NoSuchAlgorithmException ex) {
77	            throw new IllegalStateException(ex);
78	        }
79	    }
80	
81	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
82	    static String normalizeName(String value) {
83	        if (value == null) {
84	            return "";
85	        }
86	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
87	    }
88	}
