1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Duplicate-detection step of {@code POST /api/owners}: rejects the request 409 when the new owner
11	 * duplicates an existing one. Because the {@code householdId} is now deterministic &mdash; derived
12	 * from the last name and postcode (see {@link OwnerIdentity#householdId(String, String)}) &mdash;
13	 * two owners sharing a last name and postcode belong to the <em>same</em> household, and a second
14	 * such owner is a household duplicate.
15	 *
16	 * <p>Only an <b>exact identity</b> conflict is rejected: the whole {@code identityKey}
17	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}) matches an
18	 * existing owner. Because the telephone is part of the key, two members of the same household (same
19	 * {@code householdId}) with different telephones have different keys and are both admitted &mdash; a
20	 * further household member is no longer rejected as a duplicate. Instead the new member's standing is
21	 * bounded downstream by {@link CapMembershipLevel}, which caps their membership level to one above
22	 * the highest already held in the household.
23	 *
24	 * <p>Runs after the normalize steps (so telephone is E.164 and email lower-cased) and before
25	 * {@link BuildOwner}, so no owner is persisted on conflict. The {@code householdId} is derived
26	 * exactly as {@link AssignHouseholdId} will later stamp it.
27	 */
28	public class RequireUniqueIdentity {
29	
30	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
31	            throws DuplicateIdentityException {
32	        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
33	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (Boolean.TRUE.equals(existing.getDeleted())) {
36	                continue; // a soft-deleted owner no longer blocks a new registration
37	            }
38	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
39	                    existing.getHouseholdId());
40	            if (identityKey.equals(existingKey)) {
41	                throw new DuplicateIdentityException(identityKey);
42	            }
43	        }
44	    }
45	}
