1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Step of {@code POST /api/owners}: stamps the new owner with its deterministic {@code householdId}.
8	 *
9	 * <p>The identifier is derived purely from the owner's last name and postcode (see
10	 * {@link OwnerIdentity#householdId(String, String)}), so every owner sharing a last name and
11	 * postcode carries the same value automatically &mdash; there is nothing to link and no existing
12	 * owner is touched. An owner with no postcode has no household and is left with a null
13	 * {@code householdId}. The {@code sharesHousehold} flag plays no part here: it only decides, back in
14	 * {@link RequireUniqueIdentity}, whether an owner joining an existing household is allowed rather
15	 * than rejected as a household duplicate.
16	 *
17	 * <p>Runs after {@link BuildOwner}, under the write transaction.
18	 */
19	public class AssignHouseholdId {
20	
21	    public void service(@Val Owner owner) {
22	        owner.setHouseholdId(OwnerIdentity.householdId(owner.getLastName(), owner.getPostcode()));
23	    }
24	}
