1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners}: records on the owner the size of its household after this
9	 * create — the number of owners sharing its {@code householdId} once the new owner is included.
10	 * Runs after {@link AssignHouseholdId} (which stamps the deterministic identifier on the new owner)
11	 * and before the owner is persisted. Because the {@code householdId} is derived from the last name
12	 * and postcode, existing housemates already carry the same value, so it counts the existing members
13	 * carrying the same {@code householdId} plus the new owner itself.
14	 *
15	 * <p>An owner with no household leaves the size null.
16	 */
17	public class CountHouseholdMembers {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = owner.getHouseholdId();
21	        if (householdId == null) {
22	            return;
23	        }
24	        int count = 1; // the new owner, not yet persisted
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (householdId.equals(existing.getHouseholdId())) {
27	                count++;
28	            }
29	        }
30	        owner.setHouseholdSize(count);
31	    }
32	}
