1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.MembershipLevel;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Step of {@code POST /api/owners}: records the membership-level ceiling for the new owner.
10	 *
11	 * <p>A new owner joining an existing household cannot be granted a membership level more than one
12	 * above the highest level already held by a household member. This step scans the owners already
13	 * sharing the new owner's {@code householdId}, takes the maximum of their derived membership levels
14	 * and stores {@code max + 1} as the new owner's {@code membershipLevelCap}. {@link MembershipLevel}
15	 * then clamps the points-derived level to this cap when producing the response and audit line.
16	 *
17	 * <p>With no existing household member (or no household at all) there is no ceiling, so the cap is
18	 * left null and the points-derived level stands. Runs after {@link AssignHouseholdId} has stamped
19	 * the {@code householdId} and before the owner is persisted, so the new owner itself is not yet
20	 * among the existing members counted here.
21	 */
22	public class CapMembershipLevel {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String householdId = owner.getHouseholdId();
26	        if (householdId == null) {
27	            return;
28	        }
29	        Integer maxLevel = null;
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (householdId.equals(existing.getHouseholdId())) {
32	                int level = MembershipLevel.of(existing);
33	                if (maxLevel == null || level > maxLevel) {
34	                    maxLevel = level;
35	                }
36	            }
37	        }
38	        if (maxLevel != null) {
39	            owner.setMembershipLevelCap(maxLevel + 1);
40	        }
41	    }
42	}
