1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
8	
9	/**
10	 * Step of {@code POST /api/owners}: rejects an owner whose {@code email} domain is on the
11	 * disposable-domain blocklist. Email is optional, so a null/blank value is left untouched (it runs
12	 * after {@link NormalizeOwnerEmail}, which has already trimmed, lower-cased and syntactically
13	 * validated any present value). A present email whose domain matches a blocked domain is rejected
14	 * 400 via {@link DisposableEmailDomainException}.
15	 */
16	public class RequireEmailDomain {
17	
18	    /** Disposable email domains that are not accepted for owner registration. */
19	    private static final Set<String> BLOCKED_DOMAINS =
20	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
21	
22	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
23	        String email = request.getEmail();
24	        if (email == null || email.isBlank()) {
25	            return; // optional when absent
26	        }
27	        int at = email.lastIndexOf('@');
28	        if (at < 0) {
29	            return; // syntax already validated upstream; nothing to classify
30	        }
31	        String domain = email.substring(at + 1).toLowerCase();
32	        if (BLOCKED_DOMAINS.contains(domain)) {
33	            throw new DisposableEmailDomainException(email);
34	        }
35	    }
36	}
