6	
7	/**
8	 * Second step of {@code POST /api/owners}: normalises the telephone to E.164 form (strip spaces,
9	 * dashes and brackets; keep a leading {@code '+'} and country code, else assume {@code '+61'} and
10	 * drop a single leading {@code '0'}; require 8 to 15 digits after the {@code '+'}, and the correct
11	 * national-number length for a known country code &mdash; {@code +61} needs 9 national digits,
12	 * {@code +1} needs 10). The E.164 value is written back onto the (shared) request DTO so it is
13	 * stored and returned as {@code telephone}; anything that cannot form valid E.164 is rejected 400
14	 * via {@link InvalidTelephoneException}.
15	 */
16	public class NormalizeOwnerTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
19	        String e164 = E164Telephone.normalize(request.getTelephone());
20	        if (e164 == null) {
21	            throw new InvalidTelephoneException(request.getTelephone());
22	        }
23	        request.setTelephone(e164);
24	    }
25	}
