1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Normalises telephone numbers to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form.
8	 *
9	 * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are kept
10	 * as given; otherwise country code {@code +61} is assumed and a single leading {@code '0'} is
11	 * dropped from the national digits. The result is a {@code '+'} followed by 8 to 15 digits, so
12	 * {@code "0412 345 678"} becomes {@code "+61412345678"}.
13	 *
14	 * <p>For known country codes the national-number length is checked as well: {@code +61} requires 9
15	 * national digits and {@code +1} requires 10. A number whose national part is the wrong length for
16	 * its country is rejected (returns {@code null}).
17	 */
18	final class E164Telephone {
19	
20	    /**
21	     * Country code (without the {@code '+'}) to its required national-number length. Ordered
22	     * longest-prefix first so a {@code +61} number is matched by {@code "61"} before {@code "1"}.
23	     */
24	    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();
25	
26	    static {
27	        NATIONAL_LENGTH.put("61", 9);
28	        NATIONAL_LENGTH.put("1", 10);
29	    }
30	
31	    private E164Telephone() {
32	    }
33	
34	    /**
35	     * Returns the E.164 form of {@code raw}, or {@code null} when it cannot form a valid E.164
36	     * number: non-digit content after stripping separators, not 8 to 15 digits after the
37	     * {@code '+'}, or the wrong national-number length for a known country code ({@code +61} needs 9
38	     * national digits, {@code +1} needs 10).
39	     */
40	    static String normalize(String raw) {
41	        if (raw == null) {
42	            return null;
43	        }
44	        // Strip spaces, dashes and brackets.
45	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
46	        String digits;
47	        if (cleaned.startsWith("+")) {
48	            // Keep the leading '+' and country code as given.
49	            digits = cleaned.substring(1);
50	        }
51	        else {
52	            // No country code: assume '+61' and drop a single leading '0' from the national digits.
53	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
54	            digits = "61" + national;
55	        }
56	        if (!digits.matches("\\d{8,15}")) {
57	            return null;
58	        }
59	        // Enforce the national-number length for recognised country codes.
60	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTH.entrySet()) {
61	            String code = country.getKey();
62	            if (digits.startsWith(code)) {
63	                if (digits.length() - code.length() != country.getValue()) {
64	                    return null;
65	                }
66	                break;
67	            }
68	        }
69	        return "+" + digits;
70	    }
71	}
