7	/**
8	 * Delete step of {@code DELETE /api/owners/{id}}: a <em>soft</em> delete. Rather than removing the
9	 * row, it flags the owner {@code deleted} and saves it, so the record is retained and a later
10	 * {@code GET /api/owners/{id}} still returns it (with {@code deleted} true). A soft-deleted owner is
11	 * ignored by the create endpoint's duplicate/identity checks.
12	 */
13	public class DeleteOwner {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        owner.setDeleted(true);
17	        ownerRepository.save(owner);
18	    }
19	}
