3	/**
4	 * Thrown when a create-owner request's whole {@code identityKey} already belongs to another owner.
5	 * Handled by {@link DuplicateIdentityExceptionHandler}, which responds 409 Conflict.
6	 */
7	public class DuplicateIdentityException extends Exception {
8	
9	    private final String identityKey;
10	
11	    public DuplicateIdentityException(String identityKey) {
12	        super("Owner identity is already used by another owner: " + identityKey);
13	        this.identityKey = identityKey;
14	    }
15	
16	    public String getIdentityKey() {
17	        return this.identityKey;
18	    }
19	}
